head.script:
scwin.getType = function(info) {
    var dynamicId = Math.floor(Math.random() * Math.random() * 1000); //ID중복 방지용
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var colId = info.colID;
    var val = dataList1.getCellData(rowIndex, "col1");
    var rtn = {};
    rtn["options"] = {};
    if (val == "checkbox") {
        rtn["inputType"] = "checkbox";
    } else if (val == "radio") {
        rtn["inputType"] = "radio";
    } else if (val == "text") {
        rtn["inputType"] = "text";
        rtn["options"]["maxLength"] = "10";
    } else if (val == "select") {
        rtn["inputType"] = "select";
        rtn["options"]["viewType"] = "icon";
        rtn["itemSet"] = {};
        rtn["itemSet"]["nodeset"] = "data:dataList2";
        rtn["itemSet"]["label"] = "col2";
        rtn["itemSet"]["value"] = "col1";
    } else if (val == "autoComplete") {
        rtn["inputType"] = "autoComplete";
        rtn["options"]["viewType"] = "icon";
        rtn["itemSet"] = {};
        rtn["itemSet"]["nodeset"] = "data:dataList2";
        rtn["itemSet"]["label"] = "col2";
        rtn["itemSet"]["value"] = "col1";
    } else if (val == "button") {
        rtn["inputType"] = "button";
    } else if (val == "calendar") {
        rtn["inputType"] = "calendar";
        rtn["options"]["viewType"] = "icon";
        rtn["options"]["displayFormatter"] = "ngmf.rtnCalendarDate"; //자동으로 날짜 표시
    } else if (val == "textImage") {
        rtn["inputType"] = "textImage";
        rtn["options"]["viewType"] = "icon";
        rtn["options"]["imageSrc"] = "/TEST/skt/lib/images/btn_lov.png";
        rtn["options"]["imageWidth"] = "20";
        rtn["options"]["imageHeight"] = "20";
    }
    if (!(gridView1.getCellReadOnly(rowIndex, colIndex) && gridView1.getCellDisabled(rowIndex, colIndex))) { // custom 에서 readonly 또는 disabled 제어시에는 체크로직 필요.
        //					gridView1.setCellReadOnly( rowIndex , colIndex , true );	// 에디터 제어
        //					gridView1.setCellDisabled( rowIndex , colIndex , true );
    }
    rtn["id"] = "dynamic_" + rtn["inputType"] + "_" + dynamicId + "_" + rowIndex + "_" + colIndex;
    return rtn;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.gridView1_oneditkeyup = function(info) {
    //alert(1);
    log = "1";
};
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_2_1').simulate('key-combo', {
        combo: 'UP_ARROW'
    });
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_2_1').simulate('key-combo', {
        combo: 'DOWN_ARROW'
    });
}
scwin.setSimulate3 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_2_1').simulate('key-combo', {
        combo: 'LEFT_ARROW'
    });
}
scwin.setSimulate4 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_2_1').simulate('key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. text컬럼의 입력필드에 마우스를 더블클릭(edit모드)하고 키보드의 방향키(위,아래,좌,우)를 각각 실행한다.
    //2. Double-click (edit mode) on the input field of the text column and execute the direction keys (up, down, left, right) of the keyboard respectively.
    WebSquare.wUnit.addCommand("set", "scwin.fireDbClick($p.id+'gridView1_cell_2_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 입력모드로 변경되고 키보드의 방향키가 이동시 이벤트(alert = 1값)가 실행되어 보여진다.(이전에는 이벤트 실행안됨)
    //2. It changes to input mode and event (alert = 1 value) is executed when the direction key of keyboard is moved. (Previous event is not executed)
    //UP
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "log = undefined");
    //DOWN
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "log = undefined");
    //LEFT
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "log = undefined");
    //RIGHT
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
